/** Simple relevance search over name, tagline, format and description. */
function searchProducts(query) {
	const q = query.trim().toLowerCase();
	if (!q) return [];
	const terms = q.split(/\s+/);
	return products.map((p) => {
		const haystack = [
			p.name,
			p.tagline,
			formatLabels[p.format],
			p.description
		].join(" ").toLowerCase();
		let score = 0;
		for (const t of terms) if (p.name.toLowerCase().includes(t)) score += 3;
		else if (haystack.includes(t)) score += 1;
		return {
			p,
			score
		};
	}).filter((r) => r.score > 0).sort((a, b) => b.score - a.score).map((r) => r.p);
}
function getProduct(slug) {
	return products.find((p) => p.slug === slug);
}
function formatPrice(paise) {
	if (paise === void 0 || paise === null || isNaN(Number(paise))) return "₹0";
	return `₹${Number(paise).toLocaleString("en-IN")}`;
}
